<?php $page_title='Lab Tests';require_once __DIR__.'/../includes/header.php';$rows=$pdo->query("SELECT l.*,p.name patient FROM lab_tests l JOIN patients p ON p.id=l.patient_id ORDER BY l.id DESC")->fetchAll();?><div class="d-flex justify-content-between mb-3"><h2>Lab Tests</h2><a href="add.php" class="btn btn-primary">+ Lab Test</a></div><div class="card p-3"><table class="table"><thead><tr><th>Date</th><th>Patient</th><th>Test</th><th>Result</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['test_date']?></td><td><?=e($r['patient'])?></td><td><?=e($r['test_name'])?></td><td><?=e($r['result'])?></td><td><?=$r['status']?></td></tr><?php endforeach;?></tbody></table></div><?php require_once __DIR__.'/../includes/footer.php';?>